<template>
  <RouterLink
    v-if="hasRouterTo"
    v-slot="{ href, navigate }"
    :to="to"
    custom
  >
    <a
      :href="href"
      :class="buttonClasses"
      :data-variant="variant"
      :data-color="color"
      :data-loading="loading ? 'true' : undefined"
      :aria-busy="loading ? 'true' : undefined"
      :aria-disabled="isDisabled ? 'true' : undefined"
      :tabindex="isDisabled ? -1 : undefined"
      @click="onRouterLinkClick($event, navigate)"
    >
      <template v-if="loading && usesCubedCenterLayout">
        <span
          class="ui-button-cubed-inner inline-flex size-full min-h-0 min-w-0 items-center justify-center [&_.ui-icon]:leading-none"
          aria-hidden="true"
        >
          <ui-icon
            :size="cubedIconSize"
            name="spinner"
            class="fa-spin"
          />
        </span>
        <span
          v-if="resolvedLoadingText"
          class="sr-only"
        >{{ resolvedLoadingText }}</span>
      </template>
      <template v-else-if="loading">
        <span
          class="ui-button-loading-inner inline-flex size-full min-h-0 min-w-0 flex-1 items-center justify-center [&_.ui-icon]:leading-none"
          aria-hidden="true"
        >
          <ui-icon
            :size="inlineIconSize"
            name="spinner"
            class="fa-spin"
          />
        </span>
        <span
          v-if="resolvedLoadingText"
          class="sr-only"
        >{{ resolvedLoadingText }}</span>
      </template>
      <template v-else-if="stack">
        <span
          v-if="prefixIcon"
          class="inline-flex shrink-0 items-center justify-center"
          aria-hidden="true"
        >
          <ui-icon
            :size="stackIconSize"
            :name="prefixIcon"
          />
        </span>
        <span :class="textContentClass">
          <slot />
        </span>
        <span
          v-if="suffixIcon"
          class="inline-flex shrink-0 items-center justify-center"
          aria-hidden="true"
        >
          <ui-icon
            :size="stackIconSize"
            :name="suffixIcon"
          />
        </span>
      </template>
      <template v-else-if="usesCubedCenterLayout">
        <span class="ui-button-cubed-inner inline-flex size-full min-h-0 min-w-0 items-center justify-center rounded-[inherit] [&_.ui-icon]:leading-none">
          <ui-icon
            v-if="prefixIcon"
            :size="cubedIconSize"
            :name="prefixIcon"
          />
          <ui-icon
            v-else-if="suffixIcon"
            :size="cubedIconSize"
            :name="suffixIcon"
          />
          <slot v-else />
        </span>
      </template>
      <template v-else>
        <span
          v-if="prefixIcon"
          class="inline-flex shrink-0 items-center justify-center"
          aria-hidden="true"
        >
          <ui-icon
            :size="inlineIconSize"
            :name="prefixIcon"
          />
        </span>
        <span :class="textContentClass">
          <slot />
        </span>
        <span
          v-if="suffixIcon"
          class="inline-flex shrink-0 items-center justify-center"
          aria-hidden="true"
        >
          <ui-icon
            :size="inlineIconSize"
            :name="suffixIcon"
          />
        </span>
      </template>
    </a>
  </RouterLink>
  <button
    v-else
    :type="nativeType"
    :disabled="isDisabled"
    :class="buttonClasses"
    :data-variant="variant"
    :data-color="color"
    :data-loading="loading ? 'true' : undefined"
    :aria-busy="loading ? 'true' : undefined"
    @click="onClick"
  >
    <template v-if="loading && usesCubedCenterLayout">
      <span
        class="ui-button-cubed-inner inline-flex size-full min-h-0 min-w-0 items-center justify-center [&_.ui-icon]:leading-none"
        aria-hidden="true"
      >
        <ui-icon
          :size="cubedIconSize"
          name="spinner"
          class="fa-spin"
        />
      </span>
      <span
        v-if="resolvedLoadingText"
        class="sr-only"
      >{{ resolvedLoadingText }}</span>
    </template>
    <template v-else-if="loading">
      <span
        class="ui-button-loading-inner inline-flex size-full min-h-0 min-w-0 flex-1 items-center justify-center [&_.ui-icon]:leading-none"
        aria-hidden="true"
      >
        <ui-icon
          :size="inlineIconSize"
          name="spinner"
          class="fa-spin"
        />
      </span>
      <span
        v-if="resolvedLoadingText"
        class="sr-only"
      >{{ resolvedLoadingText }}</span>
    </template>
    <template v-else-if="stack">
      <span
        v-if="prefixIcon"
        class="inline-flex shrink-0 items-center justify-center"
        aria-hidden="true"
      >
        <ui-icon
          :size="stackIconSize"
          :name="prefixIcon"
        />
      </span>
      <span :class="textContentClass">
        <slot />
      </span>
      <span
        v-if="suffixIcon"
        class="inline-flex shrink-0 items-center justify-center"
        aria-hidden="true"
      >
        <ui-icon
          :size="stackIconSize"
          :name="suffixIcon"
        />
      </span>
    </template>
    <template v-else-if="usesCubedCenterLayout">
      <span class="ui-button-cubed-inner inline-flex size-full min-h-0 min-w-0 items-center justify-center rounded-[inherit] [&_.ui-icon]:leading-none">
        <ui-icon
          v-if="prefixIcon"
          :size="cubedIconSize"
          :name="prefixIcon"
        />
        <ui-icon
          v-else-if="suffixIcon"
          :size="cubedIconSize"
          :name="suffixIcon"
        />
        <slot v-else />
      </span>
    </template>
    <template v-else>
      <span
        v-if="prefixIcon"
        class="inline-flex shrink-0 items-center justify-center"
        aria-hidden="true"
      >
        <ui-icon
          :size="inlineIconSize"
          :name="prefixIcon"
        />
      </span>
      <span :class="textContentClass">
        <slot />
      </span>
      <span
        v-if="suffixIcon"
        class="inline-flex shrink-0 items-center justify-center"
        aria-hidden="true"
      >
        <ui-icon
          :size="inlineIconSize"
          :name="suffixIcon"
        />
      </span>
    </template>
  </button>
</template>

<script>
import { Comment, Fragment, Text } from 'vue'
import { RouterLink } from 'vue-router'
import { resolveThemeControlSize } from '../theme/resolve-theme-default.js'
import { resolveUiText } from '../utils/resolve-ui-text.js'
import {
  resolveThemeDefault,
} from '../theme/resolve-theme-default.js'

const sizes = ['sm', 'md', 'lg']
const variants = ['solid', 'outline', 'ghost', 'link', 'nav']
const colors = ['primary', 'secondary', 'input', 'warning', 'success', 'info', 'danger']

const NATIVE_TYPES = ['button', 'submit', 'reset']

const sizeClasses = {
  sm: 'ui-control-h-sm',
  md: 'ui-control-h-md',
  lg: 'ui-control-h-lg',
}

/** Pill (`rounded-full`) — yükseklik/padding; köşe yuvarlaklığı size sınıfından gelmez */
const pillSizeClasses = {
  sm: 'box-border h-[var(--ui-control-h-sm)] min-h-[var(--ui-control-h-sm)] px-2.5 py-0 text-xs leading-4',
  md: 'box-border h-[var(--ui-control-h-md)] min-h-[var(--ui-control-h-md)] px-3 py-0 text-sm leading-5',
  lg: 'box-border h-[var(--ui-control-h-lg)] min-h-[var(--ui-control-h-lg)] px-4 py-0 text-base leading-6',
}

/** `cubed` + ikon/kısa metin: kare kutular; ölçü `themes/components.css` `.ui-control-cubed-*` */
const cubedSizeClasses = {
  sm: 'ui-control-cubed-sm aspect-square',
  md: 'ui-control-cubed-md aspect-square',
  lg: 'ui-control-cubed-lg aspect-square',
}

/** İkon üstte, etiket altta — satır yüksekliğine (segment tab) uzanır, daire kalır */
const stackSizeClasses = {
  sm: 'aspect-square h-auto w-auto self-stretch shrink-0 !min-h-0 !min-w-0 px-1 py-0.5 text-[10px] leading-none',
  md: 'aspect-square h-auto w-auto self-stretch shrink-0 !min-h-0 !min-w-0 px-1 py-0.5 text-[10px] leading-none',
  lg: 'aspect-square h-auto w-auto self-stretch shrink-0 !min-h-0 !min-w-0 px-1 py-0.5 text-[10px] leading-none',
}

const linkSizeClasses = {
  sm: 'text-xs',
  md: 'text-sm',
  lg: 'text-base',
}

/**
 * Tam sınıf dizeleri (Tailwind JIT). `variant` × `color`.
 * Renkler `themes/default.css` + `tailwind-preset.cjs` token’larından gelir.
 */
const VARIANT_COLOR_CLASSES = {
  solid: {
    primary:
      'border-0 bg-primary text-primary-foreground shadow-none hover:opacity-90',
    secondary:
      'border border-transparent text-foreground shadow-none',
    input:
      'border-0 shadow-none',
    warning:
      'border-0 bg-warning text-warning-foreground shadow-none hover:opacity-90',
    success:
      'border-0 bg-success text-success-foreground shadow-none hover:opacity-90',
    info: 'border-0 bg-info text-info-foreground shadow-none hover:opacity-90',
    danger:
      'border-0 bg-destructive text-destructive-foreground shadow-none hover:opacity-90',
  },
  outline: {
    primary:
      'border border-current bg-transparent text-primary shadow-none hover:bg-primary/10',
    secondary:
      'border bg-transparent text-foreground shadow-none hover:bg-[var(--input-background)]',
    warning:
      'shadow-none border border-current bg-transparent text-warning hover:bg-warning/10',
    success:
      'shadow-none border border-current bg-transparent text-success hover:bg-success/10',
    info: 'shadow-none border border-current bg-transparent text-info hover:bg-info/10',
    danger:
      'shadow-none border border-current bg-transparent text-destructive hover:bg-destructive/10',
  },
  ghost: {
    primary:
      'shadow-none border-0 bg-transparent text-foreground hover:bg-primary hover:text-primary-foreground',
    secondary:
      'shadow-none border-0 bg-transparent text-secondary-foreground hover:bg-secondary hover:text-secondary-foreground',
    warning:
      'shadow-none border-0 bg-transparent text-warning hover:bg-warning hover:text-warning-foreground',
    success:
      'shadow-none border-0 bg-transparent text-success hover:bg-success hover:text-success-foreground',
    info:
      'shadow-none border-0 bg-transparent text-info hover:bg-info hover:text-info-foreground',
    danger:
      'shadow-none border-0 bg-transparent text-destructive hover:bg-destructive hover:text-destructive-foreground',
  },
  link: {
    primary:
      'border-0 bg-transparent p-0 !h-auto !min-h-0 shadow-none font-medium text-primary underline-offset-4 hover:underline',
    secondary:
      'border-0 bg-transparent p-0 !h-auto !min-h-0 shadow-none text-secondary-foreground underline-offset-4 hover:underline',
    warning:
      'border-0 bg-transparent p-0 !h-auto !min-h-0 shadow-none text-warning underline-offset-4 hover:underline',
    success:
      'border-0 bg-transparent p-0 !h-auto !min-h-0 shadow-none text-success underline-offset-4 hover:underline',
    info: 'border-0 bg-transparent p-0 !h-auto !min-h-0 shadow-none text-info underline-offset-4 hover:underline',
    danger:
      'border-0 bg-transparent p-0 !h-auto !min-h-0 shadow-none text-destructive underline-offset-4 hover:underline',
  },
  nav: {
    primary:
      'shadow-none border-0 bg-transparent text-foreground hover:bg-transparent',
    secondary:
      'shadow-none border-0 bg-transparent text-secondary-foreground hover:bg-transparent',
    input:
      'shadow-none border-0 bg-transparent text-foreground hover:bg-transparent',
    warning:
      'shadow-none border-0 bg-transparent text-warning hover:bg-transparent',
    success:
      'shadow-none border-0 bg-transparent text-success hover:bg-transparent',
    info:
      'shadow-none border-0 bg-transparent text-info hover:bg-transparent',
    danger:
      'shadow-none border-0 bg-transparent text-destructive hover:bg-transparent',
  },
}

export default {
  name: 'Button',
  components: { RouterLink },
  props: {
    /** `vue-router` hedefi; verildiğinde `<a>` + istemci navigasyonu (`RouterLink` custom). */
    to: {
      type: [String, Object],
      default: null,
    },
    /** Native `<button type="...">` — `to` yokken; forms için `submit` / `reset`. */
    nativeType: {
      type: String,
      default: 'button',
      validator: (value) => NATIVE_TYPES.includes(value),
    },
    variant: {
      type: String,
      default: 'solid',
      validator: (value) => variants.includes(value),
    },
    color: {
      type: String,
      default: 'primary',
      validator: (value) => colors.includes(value),
    },
    size: {
      type: String,
      default: undefined,
      validator: (value) => value == null || sizes.includes(value),
    },
    prefixIcon: {
      type: String,
      default: null,
    },
    suffixIcon: {
      type: String,
      default: null,
    },
    loading: {
      type: Boolean,
      default: false,
    },
    /** Boş bırakılırsa `ui.button.loading` (i18n) kullanılır */
    loadingText: {
      type: String,
      default: null,
    },
    cubed: {
      type: Boolean,
      default: false,
    },
    /**
     * İkon + metin dikey yığılır (`prefixIcon` üstte, slot altta).
     * `cubed` ile birlikte kullanılmaz.
     */
    stack: {
      type: Boolean,
      default: false,
    },
    rounded: {
      type: Boolean,
      default: false,
    },
    fulled: {
      type: Boolean,
      default: false,
    },
    /** `fulled` ile aynı — tam genişlik düğme. */
    block: {
      type: Boolean,
      default: false,
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    /**
     * Metin slot’u (ve `loading` durumunda görünen satır) yatay hizası.
     */
    textAlign: {
      type: String,
      default: 'center',
      validator: (v) => v === 'left' || v === 'center',
    },
  },
  emits: ['click'],
  computed: {
    hasRouterTo() {
      return this.to != null && this.to !== ''
    },
    /**
     * Kübik kutu: yalnız ikon veya tek slot (ör. avatar).
     * Slot varken `textContentClass` (`truncate`) kullanılmaz — kesilme olmaz.
     * Boş / comment-only default slot (ör. `v-if` kapalı) merkezi düzeni bozmasın.
     */
    usesCubedCenterLayout() {
      if (this.stack) return false
      if (!this.cubed) return false
      if (this.prefixIcon && this.suffixIcon) return false
      if (this.prefixIcon || this.suffixIcon) {
        return !this.hasRenderableDefaultSlot
      }
      return true
    },
    hasRenderableDefaultSlot() {
      const slot = this.$slots.default
      if (!slot) return false
      return slot().some((vnode) => this.isRenderableVNode(vnode))
    },
    isDisabled() {
      return this.disabled || this.loading
    },
    resolvedSize() {
      return resolveThemeControlSize(this.size, { key: 'controlSize', defaultSize: 'md' })
    },
    themeButtonRounded() {
      return resolveThemeDefault(undefined, 'buttonRounded', 'lg')
    },
    resolvedLoadingText() {
      if (this.loadingText != null && this.loadingText !== '') {
        return this.loadingText
      }
      return resolveUiText(this, 'ui.button.loading', 'Loading')
    },
    textContentClass() {
      const align = this.textAlign === 'left' ? 'text-left' : 'text-center'
      const isBlock = this.fulled || this.block
      /**
       * Tam genişlik / nav: taşmayı kısalt.
       * Normal düğmelerde truncate yok — grow/flex içinde `min-w-0` ile “QR …” gibi okunaksız kesilmeyi önler.
       */
      if (this.stack) {
        return ['ui-button-text max-w-full truncate', align].join(' ')
      }
      if (isBlock || this.variant === 'nav') {
        return ['ui-button-text min-w-0 flex-1 truncate', align].join(' ')
      }
      return ['ui-button-text whitespace-nowrap', align].join(' ')
    },
    /** Metin yanı ikonlar — küçük kontrollerde `xs`, `lg` düğmede `sm`. */
    inlineIconSize() {
      return this.resolvedSize === 'lg' ? 'sm' : 'xs'
    },
    /** Kübik düğme ikonları — kutu boyutuna göre. */
    cubedIconSize() {
      const m = { sm: 'xs', md: 'sm', lg: 'sm' }
      return m[this.resolvedSize] || 'sm'
    },
    /** Dikey yığın: segment sekmelerine yakın dokunma hedefi. */
    stackIconSize() {
      const m = { sm: 'sm', md: 'sm', lg: 'md' }
      return m[this.resolvedSize] || 'sm'
    },
    buttonClasses() {
      const isLink = this.variant === 'link'
      const isNav = this.variant === 'nav'
      let sizeOrCubed
      if (this.stack && !isLink && !isNav) {
        sizeOrCubed = stackSizeClasses[this.resolvedSize] || stackSizeClasses.md
      } else if (this.cubed && !isLink && !isNav) {
        sizeOrCubed = cubedSizeClasses[this.resolvedSize] || cubedSizeClasses.md
      } else if (isLink) {
        sizeOrCubed = linkSizeClasses[this.resolvedSize]
      } else if (isNav) {
        sizeOrCubed = 'h-auto min-h-0 w-full max-w-full justify-start overflow-hidden p-0 !min-h-0'
      } else {
        sizeOrCubed = sizeClasses[this.resolvedSize] || sizeClasses.md
      }

      let roundedClass = ''
      let sizeOrCubedResolved = sizeOrCubed
      if (!isLink && !isNav) {
        const usePill =
          this.stack ||
          this.rounded ||
          this.cubed ||
          this.themeButtonRounded === 'full'
        if (usePill) {
          roundedClass = 'rounded-full'
          if (!this.stack && !this.cubed) {
            sizeOrCubedResolved = pillSizeClasses[this.resolvedSize] || pillSizeClasses.md
          }
        }
      }

      const variantColor =
        VARIANT_COLOR_CLASSES[this.variant]?.[this.color] ||
        VARIANT_COLOR_CLASSES.solid?.primary ||
        'border-0 bg-primary text-primary-foreground shadow-none hover:opacity-90'

      const isBlock = this.fulled || this.block

      return [
        'ui-button ui-control font-sans',
        this.stack ? 'ui-button--stack' : '',
        variantColor,
        sizeOrCubedResolved,
        isBlock ? 'ui-button--fulled w-full' : '',
        roundedClass,
        this.isDisabled ? 'cursor-not-allowed opacity-50' : '',
        this.hasRouterTo ? 'inline-flex items-center' : '',
      ]
    },
  },
  methods: {
    isRenderableVNode(vnode) {
      if (vnode == null || typeof vnode !== 'object') return false
      if (vnode.type === Comment) return false
      if (vnode.type === Text) {
        return String(vnode.children ?? '').trim().length > 0
      }
      if (vnode.type === Fragment) {
        const children = vnode.children
        if (!Array.isArray(children)) return false
        return children.some((child) => this.isRenderableVNode(child))
      }
      return true
    },
    onClick(e) {
      if (this.isDisabled) return
      this.$emit('click', e)
    },
    onRouterLinkClick(e, navigate) {
      if (this.isDisabled) {
        e.preventDefault()
        return
      }
      this.$emit('click', e)
      if (e.defaultPrevented) return
      navigate(e)
    },
  },
}
</script>
